import type { Meta, StoryObj } from "@storybook/vue3";
import { h } from "vue";
import { KozmosOTPInput } from "../../index";

/**
 * Vue's OTPInput: the stories React's has, with the same names and args,
 * each drawn as React's story draws it, inside the KozmosThemeProvider the
 * Storybook's decorator gives every story.
 * test/parity/otpinput.parity.spec.ts draws each in both and holds Vue's
 * render to React's. Generated by `port OTPInput`; the stories React draws
 * by hand written by hand.
 */
type Args = Record<string, unknown>;

/** React's args as Vue's props: a controlled `value` is `v-model`'s. */
const vueArgs = (args: Args) => {
  const { value, ...rest } = args;
  return value === undefined ? rest : { ...rest, modelValue: value };
};

const meta: Meta<Args> = {
  title: "Vue/Core/Inputs/OTPInput",
  component: KozmosOTPInput,
  parameters: { layout: "centered" },
  argTypes: {
    length: { control: "select", options: [4, 6] },
    status: {
      control: "select",
      options: ["default", "error", "warning", "success"],
    },
  },
};

export default meta;
type Story = StoryObj<Args>;

/** The field in a 320 box, drawn from the story's args. */
const boxed = (args: Args) => ({
  setup: () => () =>
    h("div", { class: "w-80" }, [h(KozmosOTPInput, vueArgs(args))]),
});

export const Default: Story = {
  args: {
    helperText: "Enter the code we sent.",
    label: "Verification code",
    length: 6,
    value: "135826",
  },
  render: boxed,
};

export const WithError: Story = {
  args: {
    error: "Invalid security code.",
    label: "Verification code",
    length: 6,
    value: "135826",
  },
  render: boxed,
};

/**
 * An uncontrolled field that starts with a code: `default-value` is read on
 * mount, and the field keeps what is typed after it. A code the host passes
 * this way is not the user's, so it tracks no completion.
 */
export const WithDefaultValue: Story = {
  args: {
    defaultValue: "135826",
    helperText: "We filled in the code from your message.",
    label: "Verification code",
    length: 6,
  },
  // default-value is read on mount: a new key draws the control's code.
  render: (args) => ({
    setup: () => () =>
      h("div", { class: "w-80" }, [
        h(KozmosOTPInput, { key: String(args.defaultValue), ...vueArgs(args) }),
      ]),
  }),
};

export const ValidationStates: Story = {
  render: () => ({
    setup: () => () =>
      h("div", { class: "grid w-80 gap-4" }, [
        h(KozmosOTPInput, {
          helperText: "Use the latest code.",
          label: "Default",
          length: 6,
          modelValue: "135826",
        }),
        h(KozmosOTPInput, {
          helperText: "This code expires soon.",
          label: "Warning",
          length: 6,
          status: "warning",
          modelValue: "135826",
        }),
        h(KozmosOTPInput, {
          helperText: "Code verified.",
          label: "Success",
          length: 6,
          status: "success",
          modelValue: "135826",
        }),
        h(KozmosOTPInput, {
          error: "Invalid security code.",
          label: "Error",
          length: 6,
        }),
      ]),
  }),
};
